// The demo hub (specs/014, FR-9): `acme/hub`, the Jekyll monorepo that would present the demo
// fleet's harness — as committed files in the real hub's shapes, so the Harness tab in the
// demo exercises the real hub reader. The health file is generated by the real engine at
// construction time (parity by construction, like the demo's compiled workflows), with one
// wire deliberately tripped: the ungated nightly on acme/storefront spends 3× the fleet median.

import {
  DEFAULT_CONFIG,
  harnessHealth,
  stampUtc,
  type ActionsUsage,
  type FleetTriage,
  type HarnessSignals,
  type IssuePipeline,
  type TokenRotation,
} from '../harness/health';
import { yamlDump } from '../harness/manifest-yaml';
import { DEMO_HUB, DEMO_HUB_PULSE_CRON, DEMO_REPOS } from './fixtures';

export { DEMO_HUB };
const HOUR = 3_600_000;

const stamp = (ms: number): string => stampUtc(new Date(ms));

/** The four fleet signals the demo hub's fleet-pulse would have committed (stamped 2h ago). */
export function demoHubSignals(now: number): Required<HarnessSignals> {
  const at = stamp(now - 2 * HOUR);
  const actions_usage: ActionsUsage = {
    generated_at: at,
    totals: {
      success_rate_pct: 84.6,
      effectiveness_pct: 76.3,
      total_min: 1842.5,
      waste_min: 318.0,
      waste_hours: 5.3,
    },
    workflows: [
      { repo: 'storefront', workflow: 'Nightly (ungated)', path: '.github/workflows/nightly.yml', avg_min: 19.5, runs: 14, success: 9, external: false },
      { repo: 'storefront', workflow: 'CI', path: '.github/workflows/ci.yml', avg_min: 4.2, runs: 61, success: 57, external: false },
      { repo: 'storefront', workflow: 'Deploy', path: '.github/workflows/deploy.yml', avg_min: 6.1, runs: 12, success: 12, external: false },
      { repo: 'storefront', workflow: 'Content Factory', path: '.github/workflows/factory--content-factory.yml', avg_min: 5.4, runs: 14, success: 13, external: false },
      { repo: 'design-system', workflow: 'CI', path: '.github/workflows/ci.yml', avg_min: 3.1, runs: 48, success: 47, external: false },
      { repo: 'design-system', workflow: 'Release', path: '.github/workflows/release.yml', avg_min: 5.8, runs: 6, success: 6, external: false },
      { repo: 'infra', workflow: 'Deploy (production)', path: '.github/workflows/deploy.yml', avg_min: 7.4, runs: 9, success: 8, external: false },
      { repo: 'infra', workflow: 'Terraform plan', path: '.github/workflows/plan.yml', avg_min: 2.6, runs: 22, success: 21, external: false },
      { repo: 'infra', workflow: 'Stale Sweep', path: '.github/workflows/stale-sweep.yml', avg_min: 0.4, runs: 2, success: 2, external: false },
    ],
  };
  const fleet_triage: FleetTriage = { generated_at: at, totals: { failing_workflows: 3, repos_red: 1 } };
  const issue_pipeline: IssuePipeline = {
    generated_at: at,
    totals: { pipeline_prs: 4, stages: { intake: 9, ready: 3, 'in-pr': 4, blocked: 2, done: 17, hold: 0 } },
  };
  const token_rotation: TokenRotation = {
    generated_at: at,
    tokens: [
      { name: 'CLAUDE_CODE_OAUTH_TOKEN', oldest_age_days: 12, max_age_days: 45 },
      { name: 'FLEET_TOKEN', oldest_age_days: 30, max_age_days: 45 },
    ],
  };
  return { actions_usage, fleet_triage, issue_pipeline, token_rotation };
}

const HEADER = (what: string): string =>
  `# ${what} — generated by the demo hub's fleet-pulse (fictional: acme/hub presents the demo fleet).\n`;

/** The demo hub's committed file tree. */
export function demoHubFiles(now: number): Map<string, string> {
  const files = new Map<string, string>();
  const signals = demoHubSignals(now);
  const health = harnessHealth(signals, DEFAULT_CONFIG, new Date(now));

  files.set(
    '_data/fleet.yml',
    HEADER('Fleet registry + harness thresholds') +
      yamlDump({
        hub: DEMO_HUB,
        repos: DEMO_REPOS.map((slug) => ({ slug, branch: 'main' })),
        harness: DEFAULT_CONFIG,
      }),
  );
  files.set('_data/actions_usage.yml', HEADER('Actions usage') + yamlDump(signals.actions_usage));
  files.set('_data/fleet_triage.yml', HEADER('Fleet triage') + yamlDump(signals.fleet_triage));
  files.set('_data/issue_pipeline.yml', HEADER('Issue pipeline') + yamlDump(signals.issue_pipeline));
  files.set('_data/token_rotation.yml', HEADER('Token rotation') + yamlDump(signals.token_rotation));
  files.set('_data/harness_health.yml', HEADER('Harness health (dash-gen harness)') + yamlDump(health));

  files.set(
    'fleet.manifest.yml',
    yamlDump({
      spec_version: 'fleet/v1',
      repo: DEMO_HUB,
      provenance: 'declared',
      summary: 'The demo hub: a daily pulse, an issue pipeline, an @claude mention handler, and the dash build.',
      lanes: [
        {
          id: 'fleet-pulse',
          kind: 'maintenance',
          harness: 'engine',
          implementation: '.github/workflows/fleet-pulse.yml',
          description: 'Daily: refresh the fleet signals and recompute the harness health file.',
          triggers: [{ kind: 'schedule', cron: DEMO_HUB_PULSE_CRON }, { kind: 'dispatch' }],
          switch: null,
          uses_tokens: ['FLEET_TOKEN'],
          guardrails: { never_merges: true, opens_pull_requests: false, writable_paths: ['_data/'] },
        },
        {
          id: 'issue-pipeline',
          kind: 'triage',
          harness: 'claude-code-action',
          implementation: '.github/workflows/issue-pipeline.yml',
          description: 'Labels as state: intake → ready → in-pr → done, one PR per issue, never merges.',
          triggers: [{ kind: 'schedule', cron: '0 */6 * * *' }, { kind: 'dispatch' }],
          switch: 'ISSUE_PIPELINE_ENABLED',
          uses_tokens: ['CLAUDE_CODE_OAUTH_TOKEN', 'FLEET_TOKEN'],
          guardrails: { never_merges: true, opens_pull_requests: true, max_writes_per_run: 3 },
        },
        {
          id: 'claude',
          kind: 'mention',
          harness: 'claude-code-action',
          implementation: '.github/workflows/claude.yml',
          description: 'The @claude mention handler on issues, comments and reviews.',
          triggers: [{ kind: 'event', events: ['issue_comment', 'issues', 'pull_request_review_comment'] }],
          switch: null,
          uses_tokens: ['CLAUDE_CODE_OAUTH_TOKEN'],
          guardrails: { never_merges: true, opens_pull_requests: true },
        },
        {
          id: 'build-dash',
          kind: 'other',
          harness: 'engine',
          implementation: '.github/workflows/build-dash.yml',
          description: 'Rebuild and publish the dashboard site from the committed data.',
          triggers: [{ kind: 'event', events: ['push'] }, { kind: 'dispatch' }],
          switch: null,
          uses_tokens: [],
          guardrails: { never_merges: true, opens_pull_requests: false },
        },
      ],
    }),
  );

  files.set(
    '.gitmodules',
    DEMO_REPOS.map((slug) => {
      const name = slug.split('/')[1];
      return `[submodule "${name}"]\n\tpath = repos/${name}\n\turl = https://github.com/${slug}.git\n\tbranch = main\n`;
    }).join(''),
  );
  files.set(
    '.github/workflows/fleet-pulse.yml',
    `name: fleet-pulse\n\n# The hub's daily loop: pull the fleet signals, recompute the harness health file, commit.\non:\n  schedule:\n    - cron: '${DEMO_HUB_PULSE_CRON}'   # daily 06:00 UTC\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  pulse:\n    runs-on: ubuntu-latest\n    timeout-minutes: 15\n    steps:\n      - uses: actions/checkout@v4\n      - run: tools/dash pulse && tools/dash harness\n        env:\n          FLEET_TOKEN: \${{ secrets.FLEET_TOKEN }}\n      - run: git add _data && git commit -m "fleet-pulse" && git push\n`,
  );
  files.set(
    'README.md',
    `# hub\n\nThe demo fleet's hub: a Jekyll site that presents and monitors the harness the fleet's repos run. Part of the GitFactory demo.\n`,
  );
  return files;
}
